method add_elements(arr: array<int>, k: int) returns (result: int)
    requires arr.Length > 0 && arr.Length <= 100 // Non-empty array with length constraint
    requires k >= 1 && k <= arr.Length // k is within the valid range
    ensures result == SumElementsWithAtMostTwoDigits(arr, k) // Postcondition relates to the sum of valid elements

// Helper function to calculate the sum of elements with at most two digits
function SumElementsWithAtMostTwoDigits(arr: array<int>, k: int): int
    requires arr.Length > 0 && arr.Length <= 100
    requires k >= 1 && k <= arr.Length
    ensures SumElementsWithAtMostTwoDigits(arr, k) >= 0 // The sum is non-negative
{
    var sum := 0;
    var count := 0;
    while count < k
        && count < arr.Length
        // Loop invariant to maintain the sum of valid elements
        invariant sum == SumOfElementsWithAtMostTwoDigits(arr, count) // Invariant for sum
        invariant count <= k
    {
        if arr[count] >= -99 && arr[count] <= 99 {
            sum := sum + arr[count]; // Include element in sum if it has at most two digits
        }
        count := count + 1;
    }
    return sum;
}

// Helper function to compute the sum of elements with at most two digits from the first 'n' elements
function SumOfElementsWithAtMostTwoDigits(arr: array<int>, n: int): int
    requires n >= 0 && n <= arr.Length
{
    var sum := 0;
    var i := 0;
    while i < n
        && i < arr.Length
    {
        if arr[i] >= -99 && arr[i] <= 99 {
            sum := sum + arr[i];
        }
        i := i + 1;
    }
    return sum;
}
